package com.example.leavemanagement.security;
import com.example.leavemanagement.request.application.*;import com.example.leavemanagement.request.persistence.*;import com.example.leavemanagement.balance.persistence.*;import com.example.leavemanagement.audit.persistence.*;import com.example.leavemanagement.policy.application.LeavePolicyQueryService;import com.example.leavemanagement.shared.api.DomainException;import com.example.leavemanagement.shared.security.CurrentActor;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ManagerAuthorizationTest {
 @Test void nonManagerCannotDecide(){var r=mock(LeaveRequestRepository.class);var service=service(r);var actor=new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),null,Set.of("EMPLOYEE"),"Employee");assertThatThrownBy(()->service.decide(actor,UUID.randomUUID(),0,null,true)).isInstanceOf(DomainException.class).hasMessageContaining("Manager access");verifyNoInteractions(r);}
 @Test void selfApprovalIsForbiddenEvenWithManagerRole(){var r=mock(LeaveRequestRepository.class);var service=service(r);var id=UUID.randomUUID();var request=mock(LeaveRequestEntity.class);when(r.lockDirectReport(any(),eq(id))).thenReturn(Optional.of(request));when(request.getEmployeeId()).thenReturn(id);var actor=new CurrentActor(UUID.randomUUID(),id,null,Set.of("EMPLOYEE","MANAGER"),"Manager");assertThatThrownBy(()->service.decide(actor,id,0,null,true)).isInstanceOf(DomainException.class).hasMessageContaining("own leave");}
 private static ManagerDecisionService service(LeaveRequestRepository r){return new ManagerDecisionService(r,mock(LeaveRequestBalanceLineRepository.class),mock(LeaveBalanceRepository.class),mock(LeaveBalanceMovementRepository.class),mock(LeaveRequestSlotRepository.class),mock(LeaveRequestStatusHistoryRepository.class),mock(AuditEventRepository.class),mock(LeavePolicyQueryService.class),mock(ManagerLeaveRequestQueryService.class));}
}
